/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let title = "";
    if (api.context.props.modalTitle && api.context.props.modalTitle.length > 0) {
        return api.context.props.modalTitle;
    }
    if (api.context.props.type == "startConference") {
        title = helpers.translateSync("Start conference call");
    } else if (api.context.props.type == "sendSms") {
        title = helpers.translateSync("Send SMS");
    } else if (api.context.props.type == "addParticipants") {
        title = helpers.translateSync("Add participants");
    }
    return title;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "selectedProvider",
		value: event.payload.item
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let initialTitle = "";
	if (api.context.props.conferenceTitle) {
        initialTitle = api.context.props.conferenceTitle;
	}
	else if (api.data.notify_conference_get_initial_data.output){
		initialTitle = api.data.notify_conference_get_initial_data.output.conferenceTitle;
	}
	return {
		propName: "conferenceTitle",
		value: initialTitle
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (api.context.props.type == 'startConference') {
        return {
            event: 'Notify Change Of Conference Call Provider',
            value: {
                'Service Provider': event.payload.item.provider
            }
        };
    } else if (api.context.props.type == 'sendSms') {
        return {
            event: 'Notify Change Of SMS Provider',
            value: {
                'Service Provider': event.payload.item.provider
            }
        };
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const initialData = api.data.notify_conference_get_initial_data.output || {};
    const conferenceMessages = initialData.conferenceMessages || {};
    if (api.context.props.type == "sendSms")
        return conferenceMessages['Select the conference bridge provider through which you want to send an SMS. Telephony providers if configured are displayed as numbers.'];
    else
        return conferenceMessages['Select the conference bridge provider through which you want to initiate the call. Telephony providers if configured are displayed as numbers.'];
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.context.props.type == "sendSms")
        return helpers.translateSync("From number");
    else
        return helpers.translateSync("Conference bridge");
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (!event.payload.fieldValue || event.payload.fieldValue.length == 0) {
        return {
            propName: "disableStart",
            value: true
        };
    } else {
        if (api.state.selectedParticipantsAndGroups.length > 0 && api.state.providerSelectors.length > 0) {
            return {
                propName: "disableStart",
                value: false
            };
        }
    }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.context.props.type == "sendSms")
    return true;
	return false;
}

