  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const initialData = api.data.notify_conference_get_initial_data.output || {};
  const conferenceMessages = initialData.conferenceMessages || {};
	if (api.context.props.type == "sendSms")
		return conferenceMessages['Please enter a text message to be sent.'] || "";
	else
		return conferenceMessages['Message to be included for participants.'] || "";
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.context.props.type == "sendSms")
        return helpers.translateSync('Message');
    else {
        const initialData = api.data.notify_conference_get_initial_data.output || {};
        const conferenceMessages = initialData.conferenceMessages || {};
        if (api.state.selectedProvider && api.state.selectedProvider.provider == "Telephony") {
            return conferenceMessages['Include a brief message for participants'] || "";
        } else {
            return conferenceMessages["Provide a brief description, this note will be stored in the conference record."] || "";
        }
    }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.context.props.type == "sendSms" && api.state.smsMaxLength)
    return api.state.smsMaxLength;
  else
  	return '160';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.context.props.type == "sendSms")
    return 'true';
  else
	  return 'false';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (!api.data.notify_conference_get_recommendations.output || !api.state.selectedParticipantsAndGroups)
        return;

    let recommendedUserIds = api.data.notify_conference_get_recommendations.output.reduce(function(accumulator, userObj) {
        if (userObj.id) {
            accumulator = [...accumulator, userObj.id];
        }
        return accumulator;
    }, []);

    let numberOfSelectedRecommendations = api.state.selectedParticipantsAndGroups.reduce(function(count, selectedUserObj) {
        if (recommendedUserIds.includes(selectedUserObj.id)) {
            count++;
        }
        return count;
    }, 0);

    if (numberOfSelectedRecommendations > 0) {
        return {
            event: 'Notify Conference Call Using Recommendation',
            value: {
                'Number Of Recommendations Selected': numberOfSelectedRecommendations
            }
        };
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
   if (api.context.props.participants && api.context.props.type === "startConference") {
        return {
            event: 'Notify Reinitiate Conference Call',
            value: {
                'Source': 'Notify Conference Dialog',
                'ServiceProvider': api.context.props.serviceProvider.provider ? api.context.props.serviceProvider.provider : ""
            }
        };
    } else if (api.context.props.type === "addParticipants") {
        return {
            event: 'Notify Add Participant',
            value: {
                'Source': 'Notify Conference Dialog'
            }
        };
    }
}

